'use client';

import { useId, useState, type ReactNode } from 'react';
import './feature-comparison.css';

export type FeatureComparisonProduct = {
  id: string;
  name: string;
  description?: string;
  price?: string;
  priceNote?: string;
  badge?: string;
  href?: string;
  actionLabel?: string;
};

export type FeatureComparisonRow = {
  id: string;
  label: string;
  description?: string;
  group?: string;
  values: Record<string, string | boolean | null>;
};

export type FeatureComparisonSelection = {
  first: FeatureComparisonProduct;
  second: FeatureComparisonProduct;
};

export type FeatureComparisonProps = {
  products: FeatureComparisonProduct[];
  features: FeatureComparisonRow[];
  title?: string;
  description?: string;
  eyebrow?: string;
  defaultProductIds?: readonly [string, string];
  onSelectionChange?: (selection: FeatureComparisonSelection) => void;
  className?: string;
};

/** Compare two distinct options, with readable values and an optional differences filter. */
export function FeatureComparison({ products, features, title = 'Find your fit.', description, eyebrow = 'A CLOSER LOOK', defaultProductIds, onSelectionChange, className = '' }: FeatureComparisonProps) {
  const uid = useId();
  const [selection, setSelection] = useState<readonly [string, string]>(() => defaultProductIds ?? [products[0]?.id ?? '', products[1]?.id ?? '']);
  const [differencesOnly, setDifferencesOnly] = useState(false);
  const first = products.find(product => product.id === selection[0]) ?? products[0];
  const second = products.find(product => product.id === selection[1] && product.id !== first?.id) ?? products.find(product => product.id !== first?.id);
  if (!first || !second) return null;

  const differingRows = features.filter(row => (row.values[first.id] ?? null) !== (row.values[second.id] ?? null));
  const rows = differencesOnly ? differingRows : features;
  const groups = [...new Set(rows.map(row => row.group ?? 'Details'))];

  function selectProduct(position: 0 | 1, id: string) {
    const next = products.find(product => product.id === id);
    if (!next || !first || !second) return;
    const nextFirst = position === 0 ? next : first;
    const nextSecond = position === 1 ? next : second;
    if (nextFirst.id === nextSecond.id) return;
    setSelection([nextFirst.id, nextSecond.id]);
    onSelectionChange?.({ first: nextFirst, second: nextSecond });
  }

  function valueContent(value: string | boolean | null | undefined) {
    if (typeof value === 'boolean') return <span className="ac-compare-boolean" data-included={value}><span aria-hidden="true">{value ? '✓' : '—'}</span><span>{value ? 'Included' : 'Not included'}</span></span>;
    return value ?? <><span aria-hidden="true">—</span><span className="ac-compare-sr">Not specified</span></>;
  }

  return <section className={`ac-feature-comparison ${className}`.trim()} aria-labelledby={`${uid}-title`}>
    <header className="ac-compare-intro"><div><p className="ac-compare-eyebrow"><span aria-hidden="true"/>{eyebrow}</p><h2 id={`${uid}-title`}>{title}</h2></div><div className="ac-compare-intro-note">{description && <p>{description}</p>}<span className="ac-compare-count"><b>{String(products.length).padStart(2, '0')}</b> options. One that feels right.</span></div></header>
    <div className="ac-compare-controls"><p>Put the details side by side.<span aria-hidden="true">↘</span></p><label className="ac-compare-filter"><input type="checkbox" checked={differencesOnly} onChange={event => setDifferencesOnly(event.target.checked)}/><span>Show differences only</span><b>{differingRows.length}</b></label></div>
    <div className="ac-compare-selectors"><span className="ac-compare-side-label">THE LINEUP <span aria-hidden="true">↗</span></span>{([first, second] as const).map((product, index) => <label key={index}><span>{index === 0 ? 'First option' : 'Second option'}</span><select aria-label={index === 0 ? 'First comparison option' : 'Second comparison option'} value={product.id} onChange={event => selectProduct(index as 0 | 1, event.target.value)}>{products.map(option => <option key={option.id} value={option.id} disabled={option.id === (index === 0 ? second.id : first.id)}>{option.name}</option>)}</select></label>)}</div>
    <table className="ac-compare-table" role="table"><caption className="ac-compare-sr">{first.name} compared with {second.name}</caption><colgroup><col/><col/><col/></colgroup><thead><tr><th scope="col"><span className="ac-compare-sr">Feature</span><span aria-hidden="true" className="ac-compare-table-label">A LITTLE CLARITY<br/>GOES A LONG WAY.</span></th>{[first, second].map((product, index) => <th key={product.id} scope="col" data-option={index}><div className="ac-compare-product-heading"><span className="ac-compare-product-index" aria-hidden="true">0{products.indexOf(product) + 1}</span>{product.badge && <span className="ac-compare-badge">{product.badge}</span>}<h3>{product.name}</h3>{product.description && <p>{product.description}</p>}{product.price && <div className="ac-compare-price">{product.price}{product.priceNote && <small>{product.priceNote}</small>}</div>}</div></th>)}</tr></thead>{groups.map(group => <CompareGroup key={group} group={group} rows={rows.filter(row => (row.group ?? 'Details') === group)} products={[first, second]} renderValue={valueContent}/>)}{rows.length === 0 && <tbody><tr><td colSpan={3} className="ac-compare-empty">{differencesOnly ? 'These options match on every listed feature.' : 'No features have been added yet.'}</td></tr></tbody>}{[first, second].some(product => product.href) && <tfoot><tr><td/><td>{first.href && <a href={first.href}>{first.actionLabel ?? `Explore ${first.name}`}<span aria-hidden="true">↗</span></a>}</td><td>{second.href && <a href={second.href}>{second.actionLabel ?? `Explore ${second.name}`}<span aria-hidden="true">↗</span></a>}</td></tr></tfoot>}</table>
    <p className="ac-compare-result" aria-live="polite" aria-atomic="true">{rows.length} of {features.length} features shown <span aria-hidden="true">/</span> Comparing {first.name} and {second.name}</p>
  </section>;
}

function CompareGroup({ group, rows, products, renderValue }: { group: string; rows: FeatureComparisonRow[]; products: readonly [FeatureComparisonProduct, FeatureComparisonProduct]; renderValue: (value: string | boolean | null | undefined) => ReactNode }) {
  return <tbody><tr className="ac-compare-group"><th colSpan={3} scope="rowgroup">{group}</th></tr>{rows.map(row => <tr key={row.id} className="ac-compare-feature" data-different={(row.values[products[0].id] ?? null) !== (row.values[products[1].id] ?? null)}><th scope="row"><span>{row.label}</span>{row.description && <small>{row.description}</small>}</th>{products.map((product, index) => <td key={product.id} data-option={index}>{renderValue(row.values[product.id])}</td>)}</tr>)}</tbody>;
}

.ac-feature-comparison, .ac-feature-comparison * { box-sizing: border-box; }
.ac-feature-comparison { --ac-compare-paper:var(--ac-compare-theme-paper, #f4f3ed); --ac-compare-ink:var(--ac-compare-theme-ink, #272d29); --ac-compare-muted:var(--ac-compare-theme-muted, #626b63); --ac-compare-line:var(--ac-compare-theme-line, #cbd0c4); --ac-compare-accent:#dce7a8; --ac-compare-focus:var(--ac-compare-theme-focus, #345c35); width:100%; max-width:1600px; margin-inline:auto; padding:clamp(24px,4%,64px); container-type:inline-size; background:var(--ac-compare-paper); color:var(--ac-compare-ink); font-family:Arial,Helvetica,sans-serif; }
.ac-compare-intro { display:grid; grid-template-columns:1.2fr 1fr; gap:36px; align-items:end; padding:8px 0 42px; }
.ac-compare-eyebrow { display:flex; align-items:center; gap:9px; margin:0 0 25px; font-size:10px; letter-spacing:.09em; }
.ac-compare-eyebrow > span { width:6px; height:6px; border-radius:50%; background:var(--ac-compare-focus); }
.ac-compare-intro h2 { max-width:13ch; margin:0; font:500 clamp(40px,6cqi,80px)/.98 Arial,Helvetica,sans-serif; letter-spacing:-.065em; white-space:pre-line; }
.ac-compare-intro-note { max-width:330px; justify-self:end; }
.ac-compare-intro-note > p { margin:0 0 24px; color:var(--ac-compare-muted); font-size:14px; line-height:1.7; }
.ac-compare-count { display:flex; align-items:baseline; gap:10px; font-size:11px; }
.ac-compare-count > b { font-size:35px; font-weight:400; letter-spacing:-.07em; }
.ac-compare-controls { display:flex; justify-content:space-between; align-items:center; gap:18px; border-top:1px solid var(--ac-compare-line); padding:15px 0; }
.ac-compare-controls > p { display:flex; align-items:center; gap:25px; margin:0; font-size:11px; }
.ac-compare-controls > p > span { font-size:22px; }
.ac-compare-filter { display:flex; align-items:center; gap:9px; min-height:44px; cursor:pointer; font-size:11px; }
.ac-compare-filter input { width:18px; height:18px; margin:0; accent-color:var(--ac-compare-ink); cursor:pointer; }
.ac-compare-filter b { display:grid; place-items:center; width:21px; height:21px; border:1px solid var(--ac-compare-line); border-radius:50%; font-size:9px; font-weight:400; }
.ac-compare-selectors { display:grid; grid-template-columns:30% 35% 35%; align-items:center; border-top:1px solid var(--ac-compare-line); }
.ac-compare-side-label { display:flex; justify-content:space-between; gap:10px; padding-right:24px; font-size:9px; letter-spacing:.08em; color:var(--ac-compare-muted); }
.ac-compare-side-label > span { font-size:23px; color:var(--ac-compare-ink); }
.ac-compare-selectors label { min-width:0; display:flex; flex-direction:column; gap:7px; padding:20px 22px; border-left:1px solid var(--ac-compare-line); }
.ac-compare-selectors label > span { font-size:9px; color:var(--ac-compare-muted); }
.ac-compare-selectors select { appearance:auto; width:100%; min-width:0; min-height:44px; padding:10px 30px 10px 12px; border:1px solid var(--ac-compare-line); border-radius:0; background:transparent; color:var(--ac-compare-ink); font:inherit; font-size:13px; }
.ac-compare-table { width:100%; border-collapse:collapse; table-layout:fixed; text-align:left; }
.ac-compare-table col:first-child { width:30%; }.ac-compare-table col:not(:first-child) { width:35%; }
.ac-compare-table th, .ac-compare-table td { overflow-wrap:anywhere; }
.ac-compare-table thead th { font-weight:400; vertical-align:top; border-top:1px solid var(--ac-compare-line); }
.ac-compare-table thead th:not(:first-child) { border-left:1px solid var(--ac-compare-line); }
.ac-compare-table-label { display:block; padding:27px 22px 20px 0; font-size:9px; line-height:1.8; letter-spacing:.06em; color:var(--ac-compare-muted); }
.ac-compare-product-heading { position:relative; min-height:230px; padding:26px 22px; }
.ac-compare-product-index { font-size:10px; color:var(--ac-compare-muted); }
.ac-compare-badge { float:right; max-width:calc(100% - 30px); padding:5px 7px; border:1px solid currentColor; border-radius:2px; font-size:8px; line-height:1.4; }
.ac-compare-product-heading h3 { margin:27px 0 9px; font:500 clamp(22px,3cqi,40px)/1.1 Arial,Helvetica,sans-serif; letter-spacing:-.05em; }
.ac-compare-product-heading p { max-width:28ch; margin:0; font-size:11px; line-height:1.6; color:var(--ac-compare-muted); }
.ac-compare-price { display:flex; flex-wrap:wrap; align-items:baseline; column-gap:8px; row-gap:3px; margin-top:25px; font-size:32px; line-height:1.2; letter-spacing:-.06em; }
.ac-compare-price small { font-size:10px; font-weight:400; letter-spacing:0; color:var(--ac-compare-muted); }
.ac-compare-table [data-option="1"] { background:var(--ac-compare-accent); }
.ac-compare-group th { padding:14px 0; border-block:1px solid var(--ac-compare-line); font-size:9px; font-weight:400; text-transform:uppercase; letter-spacing:.1em; }
.ac-compare-feature th { padding:18px 20px 18px 0; font-size:12px; line-height:1.5; font-weight:400; }
.ac-compare-feature th small { display:block; max-width:26ch; margin-top:4px; color:var(--ac-compare-muted); font-size:10px; line-height:1.6; }
.ac-compare-feature td { padding:18px 22px; border-left:1px solid var(--ac-compare-line); font-size:13px; line-height:1.5; }
.ac-compare-feature:not(:last-child) { border-bottom:1px solid var(--ac-compare-line); }
.ac-compare-feature[data-different="true"] td { font-weight:600; }
.ac-compare-boolean { display:flex; align-items:center; gap:9px; font-size:11px; font-weight:400; }
.ac-compare-boolean > span:first-child { display:grid; place-items:center; width:22px; height:22px; flex-shrink:0; border:1px solid var(--ac-compare-line); border-radius:50%; font-size:13px; }
.ac-compare-boolean[data-included="true"] > span:first-child { background:var(--ac-compare-ink); color:var(--ac-compare-paper); border-color:var(--ac-compare-ink); }
.ac-compare-boolean[data-included="false"] { color:var(--ac-compare-muted); }
.ac-compare-table tfoot { border-top:1px solid var(--ac-compare-line); }
.ac-compare-table tfoot td { padding:22px; }.ac-compare-table tfoot td:first-child { padding:0; }
.ac-compare-table tfoot a { display:flex; justify-content:space-between; align-items:center; gap:10px; min-height:44px; padding:12px; border:1px solid var(--ac-compare-ink); background:var(--ac-compare-ink); color:var(--ac-compare-paper); font-size:11px; text-decoration:none; transition:background 150ms,color 150ms; }
.ac-compare-table tfoot a:hover { background:var(--ac-compare-paper); color:var(--ac-compare-ink); }
.ac-compare-table tfoot a > span { font-size:18px; }
.ac-compare-result { display:flex; flex-wrap:wrap; align-items:center; gap:12px; margin:0; padding-top:20px; border-top:1px solid var(--ac-compare-line); color:var(--ac-compare-muted); font-size:9px; line-height:1.6; }
.ac-compare-empty { padding:32px 0; text-align:center; font-size:12px; line-height:1.6; }
.ac-feature-comparison :is(a,input,select):focus-visible { outline:2px solid var(--ac-compare-focus); outline-offset:4px; }
.ac-compare-sr { position:absolute; width:1px; height:1px; overflow:hidden; clip-path:inset(50%); white-space:nowrap; }
@container (width < 650px) {
  .ac-compare-intro { grid-template-columns:1fr; gap:25px; padding-bottom:28px; }
  .ac-compare-intro h2 { font-size:clamp(38px,9cqi,60px); max-width:17ch; }
  .ac-compare-intro-note { display:flex; justify-content:space-between; align-items:center; gap:25px; justify-self:stretch; max-width:none; }
  .ac-compare-intro-note > p { margin:0; max-width:32ch; font-size:12px; }
  .ac-compare-count { flex-direction:column; gap:2px; max-width:110px; font-size:9px; }
  .ac-compare-count > b { font-size:28px; }
  .ac-compare-controls { flex-wrap:wrap; gap:2px; }
  .ac-compare-controls > p { font-size:10px; }
  .ac-compare-filter { font-size:10px; }
  .ac-compare-selectors { grid-template-columns:1fr 1fr; gap:12px; padding:16px 0; }
  .ac-compare-side-label { display:none; }
  .ac-compare-selectors label { padding:0; border:0; }
  .ac-compare-selectors select { font-size:12px; padding-left:9px; }
  .ac-compare-table col:first-child { width:32%; }.ac-compare-table col:not(:first-child) { width:34%; }
  .ac-compare-product-heading { min-height:245px; padding:17px 10px; }
  .ac-compare-product-heading h3 { margin-top:35px; font-size:clamp(14px,4.2cqi,20px); letter-spacing:-.04em; }
  .ac-compare-product-heading p { font-size:10px; }
  .ac-compare-badge { position:absolute; top:17px; right:7px; float:none; display:block; margin:0; max-width:calc(100% - 37px); font-size:7px; padding:4px; }
  .ac-compare-price { font-size:26px; margin-top:15px; }.ac-compare-price small { font-size:9px; }
  .ac-compare-table-label { padding-right:10px; font-size:7px; }
  .ac-compare-feature th { font-size:11px; padding:15px 9px 15px 0; }.ac-compare-feature th small { font-size:9px; }
  .ac-compare-feature td { padding:15px 10px; font-size:11px; }
  .ac-compare-boolean { flex-direction:column; align-items:start; gap:5px; font-size:9px; }
  .ac-compare-table tfoot td { padding:16px 8px; }.ac-compare-table tfoot a { gap:4px; padding:8px; font-size:9px; }.ac-compare-table tfoot a > span { font-size:15px; }
  .ac-compare-group th { font-size:8px; }
}
@media (prefers-reduced-motion:reduce) { .ac-feature-comparison * { transition:none !important; } }

@container (width < 430px) {
  .ac-compare-table, .ac-compare-table :is(thead,tbody,tfoot) { display:block; width:100%; }
  .ac-compare-table colgroup { display:none; }
  .ac-compare-table thead > tr, .ac-compare-table tfoot > tr, .ac-compare-feature { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); }
  .ac-compare-table thead th:first-child { position:absolute; width:1px; height:1px; overflow:hidden; clip-path:inset(50%); }
  .ac-compare-table thead th:not(:first-child) { min-width:0; }
  .ac-compare-product-heading { min-height:238px; padding-inline:13px; }
  .ac-compare-product-heading h3 { font-size:clamp(17px,6cqi,23px); }
  .ac-compare-product-heading p { font-size:11px; }
  .ac-compare-badge { max-width:calc(100% - 43px); font-size:8px; }
  .ac-compare-price { font-size:28px; }
  .ac-compare-group { display:block; }
  .ac-compare-group th { display:block; width:100%; padding-top:24px; font-size:9px; }
  .ac-compare-feature th { grid-column:1 / -1; padding:14px 10px 10px; border-bottom:1px solid var(--ac-compare-line); font-size:12px; }
  .ac-compare-feature th small { max-width:none; font-size:10px; }
  .ac-compare-feature td { min-width:0; padding:15px 13px; font-size:12px; }
  .ac-compare-boolean { flex-direction:row; align-items:center; gap:8px; font-size:10px; }
  .ac-compare-table tfoot td:first-child { display:none; }
  .ac-compare-table tfoot td { min-width:0; padding:16px 8px; }
  .ac-compare-table tfoot a { font-size:10px; }
  .ac-compare-empty { display:block; }
}

/* Neutral surfaces follow an explicit page theme; artwork and accents keep their palette. */
:where([data-theme="light"]) .ac-feature-comparison {
  --ac-compare-theme-focus: #345c35;
  --ac-compare-theme-ink: #202722;
  --ac-compare-theme-line: #d7ded4;
  --ac-compare-theme-muted: #687269;
  --ac-compare-theme-paper: #fafbf8;
  color-scheme: light;
}
:where([data-theme="dark"], .dark) .ac-feature-comparison {
  --ac-compare-theme-focus: #b2ce9d;
  --ac-compare-theme-ink: #edf2eb;
  --ac-compare-theme-line: #3d483e;
  --ac-compare-theme-muted: #a7b3a3;
  --ac-compare-theme-paper: #191e1b;
  color-scheme: dark;
}


/* Preserve the highlighted option's green fill and contrasting ink. */
.ac-compare-table [data-option="1"] { --ac-compare-ink: #272d29; --ac-compare-muted: #626b63; --ac-compare-line: #a6b27c; --ac-compare-paper: #f4f3ed; color: #272d29; }
.ac-compare-selectors option { background: var(--ac-compare-paper); color: var(--ac-compare-ink); }
